import {
  Column,
  CreateDateColumn,
  DeleteDateColumn,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  PrimaryColumn,
} from 'typeorm';
import { ProjectEntity } from 'src/projects/models/projects.entity';
import { UserEntity } from 'src/user/models/user.entity';
import { API_CONTRACT } from 'src/common/api-contract';

/**
 * One chat message in a project. `id` is generated by the service
 * (randomUUID). Timestamps keep millisecond precision so a JS Date in the page
 * cursor round-trips exactly. The paging index
 * (project_id, created_at DESC, id) is created by the migration only, since
 * TypeORM cannot declare a DESC column.
 */
@Entity('chat_messages')
@Index('IDX_chat_messages_project_created_id', { synchronize: false })
@Index('IDX_chat_messages_user', ['user_id'])
export class ChatMessageEntity {
  @PrimaryColumn({ type: 'uuid', primaryKeyConstraintName: 'PK_chat_messages' })
  id!: string;

  @Column({ type: 'varchar' })
  project_id!: string;

  @Column({ type: 'varchar' })
  user_id!: string;

  @Column({ type: 'varchar', length: API_CONTRACT.limits.chatMessageMax })
  body!: string;

  @CreateDateColumn({ type: 'timestamptz', precision: 3, name: 'created_at' })
  created_at!: Date;

  @DeleteDateColumn({
    type: 'timestamptz',
    precision: 3,
    name: 'deleted_at',
    nullable: true,
  })
  deleted_at!: Date | null;

  @ManyToOne(() => ProjectEntity, { onDelete: 'CASCADE' })
  @JoinColumn({
    name: 'project_id',
    referencedColumnName: 'project_id',
    foreignKeyConstraintName: 'FK_chat_messages_project',
  })
  project?: ProjectEntity;

  @ManyToOne(() => UserEntity, { onDelete: 'CASCADE' })
  @JoinColumn({
    name: 'user_id',
    referencedColumnName: 'user_id',
    foreignKeyConstraintName: 'FK_chat_messages_user',
  })
  user?: UserEntity;
}
